  function anatomyFigureSvg(view) {
    const F = ANATOMY_FIG[view];
    const body = F.body.map((d) => `<path class="a-body" d="${d}"/>`).join("");
    const zones = F.zones.map((z) => `<path class="a-zone" data-muscle="${z.m}" d="${z.d}"/>`).join("");
    return `<svg class="a-svg${view === "front" ? "" : " hidden"}" data-fig="${view}" viewBox="${F.viewBox}" `
      + `role="img" aria-label="${view} muscle map" preserveAspectRatio="xMidYMid meet">`
      + `<g class="a-backdrop">${body}</g>`
      + `<g class="a-zones">${zones}</g></svg>`;
  }

  function anatomyDetailHtml(g, editable) {
    const li = (t) => `<li>${escapeHtml(t)}</li>`;
    const chip = (n, anchor) => `<span class="a-ex-chip${anchor ? " anchor" : ""}">${escapeHtml(n)}</span>`;
    const fact = (label, val) => val ? `<div class="a-fact"><span class="a-fact-label">${label}</span><span class="a-fact-val">${escapeHtml(val)}</span></div>` : "";
    return `<div class="a-card${g._edited ? " is-edited" : ""}">
      <div class="a-card-head">
        <h3>${escapeHtml(g.name)}</h3>
        <span class="a-pattern" data-pattern="${g.pattern.toLowerCase()}">${escapeHtml(g.pattern)}</span>
        ${editable ? `<button type="button" class="a-edit-btn a-edit-muscle" data-edit-muscle="${escapeHtml(g.id)}">✏️ Edit</button>` : ""}
      </div>
      <p class="a-sub">${escapeHtml(g.sub)}</p>
      <p class="a-does">${escapeHtml(g.does)}</p>
      ${g.why ? `<p class="a-why">${escapeHtml(g.why)}</p>` : ""}
      ${g._note ? `<div class="a-note"><span class="a-note-label">Coach note</span><p>${escapeHtml(g._note)}</p></div>` : ""}
      ${(ANATOMY_MUSCLES[g.id] && ANATOMY_MUSCLES[g.id].length) ? `<div class="a-muscles">
        <h4>Muscles in this group</h4>
        <ul class="a-muscle-list">${ANATOMY_MUSCLES[g.id].map((m) => `<li>${escapeHtml(m)}</li>`).join("")}</ul>
      </div>` : ""}
      <div class="a-cols">
        <div class="a-col a-cues"><h4>Coaching cues</h4><ul>${g.cues.map(li).join("")}</ul></div>
        <div class="a-col a-miss"><h4>Common mistakes</h4><ul>${g.mistakes.map(li).join("")}</ul></div>
      </div>
      ${(g.stretches || g.injuries) ? `<div class="a-cols">
        ${g.stretches ? `<div class="a-col a-stretch"><h4>Stretches</h4><ul>${g.stretches.map(li).join("")}</ul></div>` : ""}
        ${g.injuries ? `<div class="a-col a-injury"><h4>Common injuries</h4><ul>${g.injuries.map(li).join("")}</ul></div>` : ""}
      </div>` : ""}
      ${(g.warmup || g.pairs || g.frequency) ? `<div class="a-facts">
        ${fact("Warm-up", g.warmup)}${fact("Pairs with", g.pairs)}${fact("Frequency", g.frequency)}
      </div>` : ""}
      <div class="a-ex">
        <h4>Example exercises</h4>
        <div class="a-ex-chips">
          ${g.anchors.map((n) => chip(n, true)).join("")}
          ${g.accessories.map((n) => chip(n, false)).join("")}
        </div>
      </div>
      ${muscleReadMoreHtml(g)}
    </div>`;
  }

  // Strength Science: plain-language explainers for the ideas behind why
  // training makes you stronger. Rendered as tap-to-open cards below the muscle
  // explorer on the Anatomy page (coach + athlete). Static reference content.
  const STRENGTH_CONCEPTS = [
    { group: "The nervous system", tag: "Neural", icon: "lu:brain", accent: "168,120,255", items: [
      { term: "Motor unit recruitment", short: "How many muscle fibers you switch on.",
        def: "A motor unit is a single nerve plus all the muscle fibers it controls. Your body switches them on smallest first, saving the big, high-force units for when they are truly needed (the size principle). Easy efforts only wake the small ones.",
        strength: "To train your strongest fibers you have to give them a reason to show up: heavy loads, or lighter loads moved with maximum intent. Cruising through easy sets leaves your biggest engines parked." },
      { term: "Rate coding", short: "How fast those fibers fire, not just how many.",
        def: "Once a motor unit is switched on, the nervous system squeezes more force out of it by firing the nerve faster, sending impulses in a quicker, tighter train. At near-maximal efforts, when there are no more units left to recruit, faster firing is your main remaining way to make more force.",
        strength: "Rate coding is a big reason you get stronger before you get bigger: the same muscle makes more force because you taught it to fire faster. Heavy lifting and pushing every rep with real speed and intent develop it, so even a grinder should try to move the bar fast." },
      { term: "Neural gains vs. growth", short: "Why early strength jumps without new muscle.",
        def: "The first several weeks of a new program deliver quick strength gains that are mostly neural: better recruitment, faster rate coding, cleaner coordination, and less protective braking. Actual new muscle takes longer to build.",
        strength: "This is beginner gains. It also explains why advanced lifters chase strength with heavy, low-rep work: near a plateau, the nervous system, not just muscle size, is where fresh strength comes from." },
      { term: "Strength is a skill", short: "Your body learns the lift, not just the muscle.",
        def: "A heavy lift is a coordinated act: the prime movers fire hard, the stabilizers time up, and the opposing muscles relax out of the way. The nervous system gets better at this pattern with practice, the way any skill improves.",
        strength: "Part of getting stronger at squat or bench is simply getting better at that exact movement. It is why practicing the main lifts beats only training around them." },
    ] },
    { group: "Sensors and reflexes", tag: "Proprioception", icon: "lu:navigation", accent: "56,214,199", items: [
      { term: "Muscle spindles", short: "The stretch sensors woven into the muscle.",
        def: "Muscle spindles are tiny sensory organs threaded among your muscle fibers that track how far and how fast the muscle is being stretched. Sense a quick stretch and they signal the spinal cord, which fires the muscle to contract and resist being pulled any further.",
        strength: "They are the trigger behind the bounce out of the bottom of a squat and the dip before a jump. Tempo work and plyometrics teach you to use that spring, while slow, relaxed stretching quiets the spindles so your range can genuinely open up." },
      { term: "The stretch reflex", short: "A fast stretch fires a protective contraction.",
        def: "The signal a muscle spindle sends is the stretch reflex, or myotatic reflex: stretch a muscle quickly and it fires to contract, guarding it against being pulled too far. It is why you ease into a stretch rather than bounce into it.",
        strength: "That same reflex feeds the spring in explosive lifts. For flexibility, slow and relaxed stretching lets the reflex settle so your range can genuinely improve." },
      { term: "Golgi tendon organs", short: "The tension sensors guarding your tendons.",
        def: "Golgi tendon organs sit where muscle meets tendon and measure how much force is passing through. When tension climbs toward a level they read as risky, they signal the muscle to ease off, a protective response called autogenic inhibition.",
        strength: "They are the sensor behind your body's safety brake. Because the load is read at the tendon, gradual heavy exposure, not sudden max efforts, is what safely widens what you can handle." },
      { term: "The safety brake", short: "Autogenic inhibition, and how training eases it.",
        def: "Acting on the Golgi tendon signal, your body can dial force down to protect the joint when tension spikes, a built-in brake. Consistent heavy training raises that brake's threshold, letting you reach more of the strength you already own.",
        strength: "Some of your max strength gain is not new force at all, it is permission to use what was there. Gradual, heavy exposure is what turns the brake down safely." },
    ] },
    { group: "Muscle and growth", tag: "Muscle", icon: "lu:biceps", accent: "255,122,89", items: [
      { term: "Muscle fiber types", short: "Slow-twitch endurance vs. fast-twitch force.",
        def: "Type I (slow-twitch) fibers resist fatigue and are built for endurance. Type II (fast-twitch) fibers make much more force, contract faster, and tire quickly. Most muscles are a mix, and your training biases which qualities develop.",
        strength: "Strength and power lean on fast-twitch fibers. Heavy loads and explosive efforts recruit and develop them; endless light reps mostly train endurance." },
      { term: "Mechanical tension", short: "The main signal that tells muscle to grow.",
        def: "High tension held across a muscle through a full range of motion, produced by heavy load or hard effort taken close to failure, is the primary driver of muscle growth.",
        strength: "More muscle means more contractile tissue and a higher strength ceiling. Tension is the shared currency: it drives both size and, alongside neural work, force." },
      { term: "Progressive overload", short: "Give the body a reason to keep adapting.",
        def: "Gradually increasing the demand over time, whether load, reps, sets, range, or better control, forces your body to keep adapting. Repeat the exact same workout forever and progress stalls.",
        strength: "This is the master principle under everything else. No progressive overload, no lasting strength." },
      { term: "Stretch-shortening cycle", short: "Load the spring, then fire.",
        def: "When a muscle is quickly stretched (the lowering phase) then immediately reverses into shortening (the lifting phase), it stores and releases elastic energy like a loaded spring. The dip before a jump and the bounce out of the bottom of a bench both use it.",
        strength: "It is the root of power and explosive lifts. Controlled tempo work and plyometrics such as jumps and throws sharpen it." },
    ] },
    { group: "Building muscle", tag: "Hypertrophy", icon: "lu:trendingup", accent: "74,222,128", items: [
      { term: "Muscle protein synthesis", short: "The repair that actually adds size.",
        def: "A hard session raises the rate at which your muscle builds new protein for roughly a day or two afterward. Growth happens when that synthesis outpaces the normal breakdown, session after session.",
        strength: "This is why food and rest between workouts matter as much as the workout. Enough protein and recovery are what let the repaired tissue accumulate into a bigger, stronger muscle." },
      { term: "Training volume", short: "Hard sets are the main dial for growth.",
        def: "The number of hard sets you give a muscle each week is the strongest lever for how much it grows. Within reason, more quality sets means more growth, up to the point where you can no longer recover from them.",
        strength: "A bigger muscle has a higher strength ceiling, so managing weekly sets, not just how heavy you go, is a big part of getting and staying strong." },
      { term: "Proximity to failure", short: "How close to your limit the set ends.",
        def: "Sets taken within a few reps of failure recruit the most fibers and drive the most growth. Stopping well short, with lots left in the tank, leaves a good chunk of the stimulus behind.",
        strength: "You do not need to grind every set to failure, but the last few tough reps before it are where most of the muscle-building signal lives. Effort is not optional." },
      { term: "Metabolic stress (the pump)", short: "The burn and swell of hard, continuous work.",
        def: "Higher-rep sets with short rest trap blood and metabolites in the muscle, the pump you feel. It is a secondary growth signal that stacks on top of heavy mechanical tension.",
        strength: "A useful tool for adding size to smaller muscles and for training around joints that do not tolerate heavy loading well." },
      { term: "Recovery and supercompensation", short: "You grow between sessions, not during them.",
        def: "Training is only the stimulus. The actual repair and growth happen while you rest, sleep, and eat. Train again before you have recovered and you dig a hole; time it right and you come back a little stronger than before.",
        strength: "Progress is training plus recovery, not training alone. Sleep and food are not extras, they are where the adaptation is built." },
    ] },
    { group: "Length and mobility", tag: "Stretching", icon: "lu:wind", accent: "56,189,248", items: [
      { term: "Flexibility vs. mobility", short: "Passive range vs. range you control.",
        def: "Flexibility is how far a joint can be moved when something else does the moving. Mobility is how much of that range you can reach and control with your own strength. For lifting, controllable mobility is the more useful quality.",
        strength: "Strong through a full range beats loose but shaky. Mobility work is what lets you own the bottom of a squat or a deep stretch instead of just falling into it." },
      { term: "Static vs. dynamic stretching", short: "Hold-and-relax vs. move-through-range.",
        def: "Static stretching holds a lengthened position for time. Dynamic stretching moves a joint through its range again and again. Dynamic drills warm tissue up for work; long static holds are better saved for after training or a separate session.",
        strength: "Dynamic movement before you lift preps the pattern. A long, hard static stretch right before a max effort can briefly dull how much force you produce, so save it for later." },
      { term: "Stretch-mediated hypertrophy", short: "Loading a muscle while it is long grows it.",
        def: "Training a muscle under load in a stretched position, through deep ranges or lengthened partials, appears to drive extra growth compared with short, easy ranges of motion.",
        strength: "Full range of motion is not only a mobility habit. The stretched portion of a lift is some of the most productive muscle-building work you can do, so do not cut your reps short." },
      { term: "Range of motion", short: "Full ROM usually beats partial.",
        def: "Taking a lift through its complete range trains the muscle at every length it works through, and generally builds more size and usable strength than short, partial reps. Targeted partials still have a place on top of that.",
        strength: "Do not trade honest range for a heavier number. Full-range strength carries over to real life and to your other lifts far better than a shortened one." },
    ] },
    { group: "Training language", tag: "Programming", icon: "lu:milestone", accent: "251,191,36", items: [
      { term: "1RM and rep maxes", short: "The vocabulary of intensity.",
        def: "Your 1RM is the most you can lift once. A rep max (RM) is the most reps you can do at a given weight: a 5RM is a weight you can lift five times and no more. Programs often set loads as a percentage of your 1RM.",
        strength: "Knowing your maxes lets a program target the right intensity for the goal: heavy and low-rep for strength, moderate for size." },
      { term: "RPE and RIR", short: "Auto-adjusting effort to the day.",
        def: "RPE (rate of perceived exertion) rates how hard a set felt, usually on a 1 to 10 scale. RIR (reps in reserve) is the flip side: how many good reps you had left. An RPE 8 or 2 RIR set means you stopped about two reps shy of failure.",
        strength: "These let you hit the right effort on a good or bad day instead of blindly chasing a number, so you manage fatigue while still pushing." },
      { term: "Specificity (SAID)", short: "You get good at exactly what you do.",
        def: "SAID stands for Specific Adaptations to Imposed Demands: your body adapts to the precise demand you place on it, meaning the movement, speed, range, and load.",
        strength: "To get strong at a lift, train that lift and that quality. Carryover from other exercises helps, but nothing replaces practicing the thing itself." },
    ] },
  ];

  // Nutrition and body-composition explainers. Same card shape as the strength
  // concepts, but the takeaway field is `apply` (rendered under "How to use it").
  const NUTRITION_CONCEPTS = [
    { group: "Energy and calories", tag: "Basics", icon: "lu:flame", accent: "251,146,60", items: [
      { term: "Calorie", short: "The unit your body runs on.",
        def: "A calorie is simply a unit of energy. Food delivers energy, and your body spends it to move, think, digest, and stay alive. Almost everything about gaining or losing weight traces back to how the energy you eat compares to the energy you burn.",
        apply: "No single food needs to be feared. What moves the needle is your total energy over days and weeks, so judge your diet by the big picture, not one meal." },
      { term: "Energy balance", short: "Calories in versus calories out.",
        def: "Energy balance is the running total of the calories you eat against the calories you burn. Eat more than you burn and you are in a surplus. Eat less and you are in a deficit. Match them and you hold steady.",
        apply: "This is the master switch for body weight. Whatever a diet is called, it works by nudging this balance in one direction." },
      { term: "Maintenance calories", short: "The intake that holds you steady.",
        def: "Your maintenance level is the calorie intake that keeps your weight stable, because it matches your total daily burn. Eat here and you neither gain nor lose over time. It is the anchor every goal is measured from.",
        apply: "Find maintenance by tracking intake and weight for two or three weeks. Once you know it, a deficit or surplus is just a deliberate step away from that anchor." },
    ] },
    { group: "Your metabolism", tag: "TDEE", icon: "lu:gauge", accent: "34,211,238", items: [
      { term: "TDEE", short: "Everything you burn in a day.",
        def: "TDEE stands for total daily energy expenditure: every calorie you burn in 24 hours added up. It is the number your intake is really competing against, and it shifts day to day with your activity.",
        apply: "Estimate your TDEE, then eat below it to lose, above it to gain, or at it to maintain. Treat the estimate as a starting point and adjust from what the scale actually does." },
      { term: "BMR and RMR", short: "The cost of just being alive.",
        def: "Your basal or resting metabolic rate is the energy your body uses at complete rest to keep your heart, lungs, brain, and cells running. For most people it is the largest single slice of daily burn, often around 60 to 70 percent.",
        apply: "Bigger, more muscular bodies have a higher resting burn, one quiet reason building muscle helps your body composition over the long run." },
      { term: "The four parts of your burn", short: "Where daily calories go.",
        def: "Your total burn is your resting rate (staying alive) plus the thermic effect of food (digesting it) plus exercise plus NEAT (all your non-exercise movement). Exercise is usually the smallest of the four, which surprises most people.",
        apply: "Because training is a small slice, you cannot reliably out-train a poor diet. Daily movement and food intake matter more than any single workout." },
      { term: "NEAT", short: "The calories you burn just living.",
        def: "NEAT is non-exercise activity thermogenesis: everything you burn that is not a workout, from walking and chores to fidgeting and standing. It varies enormously between people and can swing hundreds of calories a day.",
        apply: "When you diet, your body quietly cuts NEAT to save energy, which stalls fat loss. Holding a daily step target protects it and keeps the deficit working." },
      { term: "Thermic effect of food", short: "The cost of digesting a meal.",
        def: "The thermic effect of food is the energy your body spends breaking down and absorbing what you eat. Protein has by far the highest cost, burning roughly a quarter of its own calories in digestion, while carbs and fat cost much less.",
        apply: "A higher-protein diet burns a little more just being processed, one more reason protein earns its place at every meal." },
      { term: "Metabolic adaptation", short: "Why your burn falls as you diet.",
        def: "As you lose weight your TDEE drops: a smaller body costs less to run, and your body trims NEAT and resting burn to defend its fat stores. This is why a deficit that once worked eventually stalls.",
        apply: "Expect to lower calories or add activity as you get leaner. A stall is not failure, it is the target moving, so adjust and keep going." },
    ] },
    { group: "Losing fat", tag: "Fat loss", icon: "lu:target", accent: "251,113,133", items: [
      { term: "Calorie deficit", short: "Eating less than you burn.",
        def: "A calorie deficit means taking in fewer calories than your body spends. It is the one requirement for fat loss. Every effective fat-loss diet, by any name, creates this in the end.",
        apply: "Aim for a moderate deficit you can hold, not the steepest one possible. Crash diets cost you muscle and rarely last." },
      { term: "How fat loss works", short: "Tapping your stored energy.",
        def: "When you run a deficit, your body makes up the shortfall by pulling energy from storage, mostly body fat. The fat cells release their contents to be burned, so the cells shrink. That shrinking is what shows up as fat loss.",
        apply: "You cannot spot-reduce: where fat comes off is set by genetics, not by which muscle you train. Train everything, hold the deficit, and be patient." },
      { term: "A sustainable rate", short: "How fast fat should come off.",
        def: "Losing roughly 0.5 to 1 percent of your bodyweight per week is a pace most people can sustain while keeping muscle and strength. Faster than that and you increasingly burn muscle and feel drained.",
        apply: "Pick a rate you can live with for months, not days. Slow and steady almost always beats fast and fragile." },
      { term: "Keeping muscle while cutting", short: "Protect what you built.",
        def: "In a deficit your body will burn muscle along with fat unless you give it strong reasons not to. Two reasons dominate: enough protein, and continued hard resistance training that signals the muscle is still needed.",
        apply: "Keep lifting heavy and keep protein high while dieting. Do not switch to light weights and endless cardio, that is how you shrink instead of getting lean." },
    ] },
    { group: "Gaining muscle and weight", tag: "Muscle gain", icon: "lu:beef", accent: "132,204,22", items: [
      { term: "Calorie surplus", short: "Eating more than you burn.",
        def: "A surplus is taking in more calories than you spend. It gives your body spare energy to build new tissue. Some surplus makes gaining muscle easier, but any excess beyond what you can use is stored as fat.",
        apply: "For gaining, a small surplus is enough. Piling on calories does not build muscle faster, it just adds fat you will have to diet off later." },
      { term: "How muscle gain works", short: "Build outpaces breakdown.",
        def: "Muscle grows when muscle protein synthesis outpaces breakdown over time. Hard training is the signal that tells the body to build, protein supplies the raw material, and enough total energy funds the work. Remove any one and growth stalls.",
        apply: "You need all three: train close to failure, eat enough protein, and do not sit in too deep a deficit. Muscle is built over months of that stack repeating." },
      { term: "How fat gain works", short: "Storing the leftovers.",
        def: "When you eat more energy than you can use or store as muscle and glycogen, the surplus is stored as body fat. It is the body banking spare energy for later, and a large surplus fills that bank quickly.",
        apply: "The bigger and longer the surplus, the more of your gain is fat. Keeping the surplus small biases the scale toward muscle instead of fat." },
      { term: "Lean bulking", short: "Gaining with the brakes on.",
        def: "A lean bulk is a small, controlled surplus, often around 100 to 300 calories over maintenance, aimed at gaining mostly muscle with minimal fat. It trades some speed for a leaner result.",
        apply: "Aim to gain a slow trickle, on the order of half a pound a week for many people. If the scale is jumping, you are gaining more fat than you need to." },
      { term: "Body recomposition", short: "Losing fat and gaining muscle at once.",
        def: "Recomposition is building muscle while losing fat at the same time, so your weight barely changes but your shape does. It is most achievable for beginners, people returning after a break, and those carrying more body fat.",
        apply: "If you are new or coming back, eat near maintenance, train hard, and keep protein high, and let the mirror rather than the scale track progress." },
      { term: "P-ratio", short: "How a surplus or deficit splits.",
        def: "Your partitioning ratio is how gained or lost energy divides between muscle and fat. In a surplus it is how much becomes muscle versus fat. In a deficit it is how much lost is fat versus muscle. Training, protein, and sleep all tilt it.",
        apply: "You cannot fully control your p-ratio, but lifting hard, eating enough protein, and sleeping well push it toward more muscle and less fat in either direction." },
    ] },
    { group: "Losing muscle", tag: "Muscle loss", icon: "lu:shield", accent: "148,163,184", items: [
      { term: "Anabolism vs. catabolism", short: "Building up versus breaking down.",
        def: "Anabolism is your body building tissue, including muscle. Catabolism is breaking tissue down for energy. Both run constantly, and which one wins over time decides whether you gain or lose muscle.",
        apply: "The word catabolic is nothing to fear. The goal is for building to outweigh breakdown across the week, not to avoid breakdown at every moment." },
      { term: "How muscle loss works", short: "Breakdown wins over time.",
        def: "Muscle is lost when breakdown outpaces synthesis for a sustained stretch. The usual causes are a large calorie deficit, too little protein, and no training signal telling the body the muscle is worth keeping.",
        apply: "Avoid all three at once. Even in a deficit, hard lifting plus enough protein keeps most of your muscle while the fat comes off." },
      { term: "Disuse atrophy", short: "Use it or lose it.",
        def: "Stop training a muscle and it gradually shrinks, a process called disuse atrophy or detraining. The body sees no reason to maintain tissue it is not using, so it lets it waste to save energy.",
        apply: "During time off, even a little work, a few hard sets a week, preserves far more muscle than doing nothing at all." },
      { term: "Muscle memory", short: "Regaining is faster than building.",
        def: "Muscle you once built comes back much faster than it took to build the first time. Your muscle fibers keep extra nuclei gained from past training, giving them a head start when you return.",
        apply: "A layoff is not the disaster it feels like. Expect lost size and strength to return in weeks, not the months it originally took." },
    ] },
    { group: "Macros and food quality", tag: "Macros", icon: "lu:sandwich", accent: "163,230,53", items: [
      { term: "Protein", short: "The building-block macro.",
        def: "Protein supplies the amino acids your body uses to repair and build muscle. It is the most important macro for body composition, the most filling, and the most costly to digest. Common targets land around 0.7 to 1 gram per pound of bodyweight.",
        apply: "Hit your protein first every day, spread across a few meals. Whether cutting or bulking, it is the macro that protects and builds muscle." },
      { term: "Carbohydrates", short: "Your main training fuel.",
        def: "Carbs are your body's preferred fuel for hard training. They are stored in muscle as glycogen and burned to power intense sets. They are not required to survive, but they make lifting feel and perform better.",
        apply: "Put carbs around your workouts to train harder. Cutting them can help control calories, but going too low often drains gym performance." },
      { term: "Dietary fat", short: "For hormones and health.",
        def: "Dietary fat supports hormone production, brain function, and the absorption of some vitamins. Some fat is essential, meaning your body cannot make it and must get it from food. It is also calorie-dense, so it adds up fast.",
        apply: "Keep fat at a sensible minimum for health, often around 0.3 grams per pound, then let carbs and fat fill whatever calories are left after protein." },
      { term: "Fiber and micronutrients", short: "The quality layer.",
        def: "Fiber, vitamins, and minerals add little energy but keep digestion, recovery, and overall health running. They come mostly from vegetables, fruit, whole grains, and other minimally processed foods.",
        apply: "Build meals around whole foods so the micronutrients take care of themselves. It also keeps you fuller on fewer calories." },
      { term: "Alcohol", short: "The fourth energy source.",
        def: "Alcohol carries 7 calories per gram, nearly as many as fat, and offers no nutritional benefit. It also blunts muscle protein synthesis and disrupts sleep, both of which work against recovery.",
        apply: "You do not have to be perfect, but heavy drinking fights your training and diet on several fronts. Count its calories and keep it modest." },
      { term: "Hydration", short: "Water drives performance.",
        def: "Water makes up most of your muscle and is needed for nearly every process, including force production and recovery. Even mild dehydration can dent strength, focus, and how full your muscles feel.",
        apply: "Drink through the day, not just at the gym. Water with each meal and during training covers most people." },
    ] },
    { group: "Putting it to work", tag: "Strategy", icon: "lu:route", accent: "196,181,253", items: [
      { term: "Setting your target", short: "From maintenance to a plan.",
        def: "Once you know your maintenance calories, a goal is simple math: subtract roughly 15 to 25 percent for fat loss, or add a small amount for lean gaining. Set protein first, then fill the rest with carbs and fat to taste.",
        apply: "Start from your real maintenance, not a generic online number, and adjust every few weeks based on what the scale and mirror show." },
      { term: "Tracking and adherence", short: "Consistency beats perfection.",
        def: "Tracking your food, whether by weighing it or by consistent habits, tells you what you are actually eating, which is usually different from what you think. The best diet is the one you can stick to across months.",
        apply: "Pick a method you will actually keep up. A slightly imperfect plan you follow beats a perfect one you quit in a week." },
      { term: "Diet breaks and refeeds", short: "Planned pauses that help you last.",
        def: "A diet break is a stretch at maintenance during a long cut. A refeed is a shorter bump in calories, mostly from carbs. Both ease the physical and mental toll of dieting and can blunt some metabolic adaptation.",
        apply: "On a long cut, schedule short breaks at maintenance. They refill glycogen, lift mood and performance, and make the whole diet easier to finish." },
      { term: "Sleep and body composition", short: "Recovery is built at night.",
        def: "Sleep is when most recovery and hormone regulation happen. Short sleep raises hunger, lowers training quality, and tilts a deficit toward losing muscle and a surplus toward gaining fat.",
        apply: "Treat sleep as part of your program, not an afterthought. Seven to nine hours does more for body composition than any supplement." },
      { term: "Cardio's role", short: "A tool, not a requirement.",
        def: "Cardio burns extra calories and improves heart health, but it is not required for fat loss, since diet creates the deficit. Too much cardio can also eat into your recovery from lifting.",
        apply: "Use cardio to widen your deficit or for health, not as the main event. Let food do most of the work and keep lifting the priority." },
    ] },
  ];

  // Hormones and the menstrual cycle. Same card shape again; the takeaway field
  // is `means` (rendered under "What it means for training"). The training and
  // appetite hormones lead, since they apply to everyone reading the page; the
  // cycle groups follow. The training layer stays deliberately hedged: the
  // mechanics of the cycle are settled physiology, but phase-based programming
  // is not.
  const HORMONE_CONCEPTS = [
    { group: "Training hormones", tag: "Anabolic", icon: "lu:zap", accent: "251,146,60", items: [
      { term: "Testosterone", short: "Present in everyone, in very different amounts.",
        def: "Testosterone supports muscle protein synthesis and is one reason for the average difference in muscle mass between men and women. Women produce it too, at roughly a tenth to a twentieth the level, and it still matters for their strength and recovery.",
        means: "Your natural level is largely out of your hands. Sleep, sensible training loads, and not staying in a deep deficit for months are the levers you actually control." },
      { term: "Growth hormone", short: "Real, but not the muscle switch it is sold as.",
        def: "Growth hormone is released in pulses, mostly during deep sleep, and supports tissue repair and fat metabolism. The temporary spike from a hard training session is small and short compared with what you produce overnight.",
        means: "The best growth-hormone strategy is unglamorous: sleep properly. Chasing the post-workout spike is not worth structuring a program around." },
      { term: "Cortisol", short: "The stress hormone, and not the villain.",
        def: "Cortisol rises with stress of any kind, including training, and helps mobilise energy. It is essential and follows a daily rhythm, peaking in the morning. The problem is not cortisol itself but chronically elevated levels from stress that never lets up.",
        means: "A hard session raising cortisol is normal and necessary. Months of poor sleep, under-eating and relentless volume together is the pattern that actually costs you progress." },
      { term: "IGF-1", short: "The messenger that does much of the work.",
        def: "Insulin-like growth factor 1 is produced largely in the liver in response to growth hormone, and acts locally in muscle to support repair and growth. It is heavily influenced by how much you eat and how much protein you get.",
        means: "This is part of why eating enough matters for gaining muscle. Chronic under-eating lowers the signals that tell muscle to rebuild." },
      { term: "The post-workout spike myth", short: "Hormone bumps do not build the muscle.",
        def: "Training briefly raises testosterone and growth hormone, and for years that was assumed to drive growth. Studies since have found these acute spikes correlate poorly with actual muscle gain, which tracks mechanical tension and training volume instead.",
        means: "Do not pick exercises to chase a hormone response. Pick them because they load the muscle you want to grow through a full range." },
    ] },
    { group: "Hunger and metabolism", tag: "Appetite", icon: "lu:drumstick", accent: "45,212,191", items: [
      { term: "Insulin", short: "The nutrient traffic controller.",
        def: "Insulin is released when blood sugar rises and moves glucose and amino acids into cells, including muscle. It is a storage hormone for both muscle and fat, and it is not the cause of fat gain on its own. Eating more energy than you burn is.",
        means: "You do not need to fear carbohydrates or insulin to lose fat. Total energy still decides the direction; insulin decides the traffic." },
      { term: "Leptin", short: "The fullness signal from fat tissue.",
        def: "Leptin is produced by fat cells and tells the brain roughly how much stored energy is available. As you lose fat, leptin falls, and the brain responds by increasing hunger and quietly reducing how much you move.",
        means: "This is the biology behind a stalling diet and rising appetite. It is a predictable response, not a personal failure, and diet breaks at maintenance help ease it." },
      { term: "Ghrelin", short: "The hunger signal from the stomach.",
        def: "Ghrelin rises before meals and falls after eating, prompting hunger. It climbs during a sustained calorie deficit and stays elevated for a while even after weight is lost.",
        means: "Protein and high-volume, fibrous foods blunt it best. Expect hunger to run higher in a deficit and plan meals around it rather than relying on willpower." },
      { term: "Thyroid hormones", short: "The pace-setter for your metabolism.",
        def: "Thyroid hormones set the rate at which your body burns energy at rest. Extended dieting can lower their output modestly, which is part of why maintenance calories drift down over a long cut.",
        means: "Some slowdown while dieting is normal adaptation, not a broken metabolism. Genuine thyroid disorders exist and are diagnosed by a blood test, not by a stalled scale." },
      { term: "Sleep and your hormones", short: "The cheapest hormonal intervention there is.",
        def: "Short sleep raises ghrelin, lowers leptin, raises cortisol, and reduces testosterone and overnight growth hormone release. Studies restricting sleep during a diet find people lose a greater share of that weight as muscle instead of fat.",
        means: "If you fix one thing on this shelf, fix sleep. It moves more of these hormones at once than any supplement on the market." },
    ] },
    { group: "How the cycle works", tag: "The cycle", icon: "lu:moon", accent: "244,114,182", items: [
      { term: "The cycle at a glance", short: "One month, two halves, one egg.",
        def: "The menstrual cycle is the monthly rhythm that prepares the body for a possible pregnancy. It is counted from the first day of one period to the first day of the next, and averages about 28 days, though anywhere from 21 to 35 is normal. Ovulation splits it into two halves: the follicular phase before, and the luteal phase after.",
        means: "Cycle length varies between people and from month to month in the same person. Counting from day 1 of your period is the only reliable way to know where you are." },
      { term: "Day 1: the period", short: "The lining sheds and a new cycle begins.",
        def: "When no pregnancy happens, the hormones holding the uterine lining in place fall away and the lining sheds. That bleeding is your period, and its first day is day 1 of a new cycle. It typically lasts three to seven days, and the blood loss is far smaller than it looks, usually a few tablespoons in total.",
        means: "Day 1 is the anchor for everything else. If you track nothing else about your cycle, track that date." },
      { term: "The follicular phase", short: "Follicles grow and estrogen climbs.",
        def: "This runs from day 1 until ovulation. The pituitary gland releases FSH, which tells a batch of fluid-filled sacs in the ovary, called follicles, to start maturing. Each holds an immature egg. One becomes dominant and the others break down. As the dominant follicle grows it releases rising amounts of estrogen, which rebuilds the uterine lining that just shed.",
        means: "This is the longer and more variable half. When a cycle runs long or short, it is almost always this phase that stretched or shrank." },
      { term: "Ovulation", short: "The egg is released.",
        def: "Estrogen climbing past a threshold flips the brain's response from damping down to spurring on, triggering a sharp surge of LH. Roughly a day after that surge, the dominant follicle ruptures and releases its egg into the fallopian tube. The egg itself survives only about 12 to 24 hours.",
        means: "Ovulation is a single event, not a phase. It sits in the middle of the cycle only if the follicular phase happened to run about two weeks." },
      { term: "The luteal phase", short: "Progesterone takes over.",
        def: "The emptied follicle collapses into a temporary gland called the corpus luteum, which produces progesterone along with some estrogen. Progesterone holds the uterine lining thick, stable, and ready to receive a fertilized egg. This half is the more consistent one, running about 12 to 14 days in most people.",
        means: "Because the luteal phase is fairly fixed, ovulation usually lands about two weeks before your next period, not two weeks after the last one." },
      { term: "The end of the cycle", short: "No pregnancy, so the signal switches off.",
        def: "Without a fertilized egg, the corpus luteum breaks down after roughly two weeks. Progesterone and estrogen both fall sharply. The lining loses the hormonal support holding it in place, and the next period starts. That steep hormone drop is behind much of what gets called premenstrual symptoms.",
        means: "The heaviest symptom window is usually the few days of falling hormones before bleeding starts, not the bleeding itself." },
      { term: "The uterine lining", short: "The tissue the whole cycle is building.",
        def: "The endometrium is the inner lining of the uterus. Estrogen thickens it through the first half of the cycle. Progesterone then matures it and holds it steady through the second half. If no pregnancy occurs it is shed and the process starts again.",
        means: "Every phase of the cycle is really about this one tissue: build it, hold it, or let it go." },
      { term: "What counts as normal", short: "A wide range, and worth knowing yours.",
        def: "Cycles anywhere from 21 to 35 days, bleeding for up to about seven days, and some variation month to month all fall inside normal. Cycles are often irregular for the first year or two after they start and again approaching menopause.",
        means: "Matching a 28-day average matters far less than knowing your own pattern, because your pattern is what tells you when something has changed." },
    ] },
    { group: "The hormones behind it", tag: "Signals", icon: "lu:droplet", accent: "167,139,250", items: [
      { term: "Estrogen", short: "The builder of the first half.",
        def: "Estrogen rises through the follicular phase as the dominant follicle grows. It rebuilds the uterine lining, and it acts well beyond the reproductive system: it supports bone density, influences tendon and ligament properties, and affects mood and sleep.",
        means: "Its role in bone and connective tissue is why chronically low estrogen, from any cause, is a genuine concern for a lifter and not just a fertility issue." },
      { term: "Progesterone", short: "The steady hand of the second half.",
        def: "Progesterone is produced by the corpus luteum after ovulation. It maintains the uterine lining, and it also raises resting body temperature slightly and has a mild sedative, calming effect on the brain.",
        means: "The small temperature rise is real and measurable, which is why waking temperature is one way people confirm that ovulation happened." },
      { term: "FSH", short: "The wake-up call for the follicles.",
        def: "Follicle stimulating hormone comes from the pituitary gland at the base of the brain. It rises at the start of the cycle and recruits a group of follicles to begin maturing.",
        means: "FSH is the opening move of the whole sequence. Everything downstream, including estrogen, depends on it firing first." },
      { term: "LH", short: "The trigger that releases the egg.",
        def: "Luteinizing hormone also comes from the pituitary. It sits low through most of the follicular phase, then spikes sharply in response to high estrogen. That surge is what causes the follicle to rupture and release its egg.",
        means: "Ovulation predictor kits work by detecting this surge in urine, which is why they flag the day before ovulation rather than the day of it." },
      { term: "The feedback loop", short: "The brain and the ovaries talk both ways.",
        def: "The hypothalamus releases GnRH, which tells the pituitary to release FSH and LH, which tell the ovaries to produce estrogen and progesterone. Those ovarian hormones then travel back to the brain and adjust the next round of signals. It is a loop, not a one-way chain.",
        means: "Because the loop starts in the brain, anything that stresses the brain's read on your situation, such as severe under-eating or extreme training loads, can quiet the whole system from the top down." },
    ] },
    { group: "The cycle and training", tag: "Training", icon: "lu:waves", accent: "56,189,248", items: [
      { term: "Does the cycle change your strength?", short: "Less, and less predictably, than you have been told.",
        def: "Cycle-phase training plans are everywhere online, but the research behind them is thin. Reviews pooling the available studies find average differences in strength and performance across phases that are small and inconsistent, with individual variation far larger than any group trend.",
        means: "Do not hand your program over to a calendar. Track how you actually feel and perform across a few cycles, and adjust to your own pattern rather than someone else's chart." },
      { term: "Training on your period", short: "Usually fine, and often helps.",
        def: "There is no physiological reason to skip training while bleeding, and many people find that movement eases cramping. Others feel genuinely worse and train lighter. Both are normal.",
        means: "Treat it like any other recovery variable. A lighter day when you feel wrecked is good coaching, not weakness, and pushing through a good day is fine too." },
      { term: "Cramps and what helps", short: "The uterus contracting, and what eases it.",
        def: "Cramps come from the uterus contracting to shed its lining, driven by compounds called prostaglandins. Heat, gentle movement, and over-the-counter anti-inflammatories are the best-supported ways to reduce them.",
        means: "Light aerobic work and mobility on a bad day beats doing nothing, but there is no need to be heroic about a heavy session." },
      { term: "Iron and heavy bleeding", short: "Blood loss is iron loss.",
        def: "Menstrual bleeding is a recurring loss of iron, and heavy periods are one of the most common causes of low iron and iron-deficiency anemia. Low iron shows up as unusual fatigue, breathlessness, and training that feels far harder than the numbers suggest.",
        means: "If your conditioning falls off a cliff for no clear reason, iron is worth asking a doctor to check with a blood test rather than guessing at supplements." },
      { term: "Bloating, water and the scale", short: "Weight that is not fat.",
        def: "Water retention commonly rises in the late luteal phase and around the period, and can move the scale by several pounds in either direction over a few days. It is fluid, not tissue.",
        means: "Expect it and do not react to it. Compare weight to the same point in your previous cycle rather than to last week, or judge the trend over a full month." },
      { term: "Temperature and sleep", short: "The luteal phase runs slightly warmer.",
        def: "Progesterone raises resting body temperature by a few tenths of a degree after ovulation and holds it there until the period. That small shift can make sleep lighter and hot rooms or hard conditioning feel harder.",
        means: "If a session in the heat feels unusually rough in the second half of your cycle, that is a real effect. Adjust rest and hydration rather than assuming you lost fitness." },
      { term: "Hormonal birth control", short: "It replaces the cycle rather than following it.",
        def: "Most hormonal contraceptives work by suppressing the natural rise and fall of your own hormones, preventing ovulation. The bleed on the placebo week of a combined pill is a withdrawal bleed caused by stopping the hormone, not a true period, and some methods stop bleeding altogether.",
        means: "If you are on hormonal contraception, cycle-phase training advice mostly does not apply to you, because the cycle it describes is not happening." },
      { term: "The injury-risk question", short: "Suggestive, not settled.",
        def: "Some research reports higher rates of ACL injury around ovulation, with estrogen's effect on ligament laxity as the proposed reason. The finding is not consistent across studies, and the size of any real effect is unclear.",
        means: "It is not a reason to avoid training at any point in the month. Warming up properly and training landing and cutting mechanics protects knees in every phase." },
    ] },
    { group: "When the cycle changes", tag: "Red flags", icon: "lu:flag", accent: "251,191,36", items: [
      { term: "Missing periods", short: "A signal worth taking seriously.",
        def: "Amenorrhea means periods have stopped, or never started. In athletes the most common cause is the brain quieting the reproductive system when it reads the body as being under too much strain, usually from not eating enough for the training being done.",
        means: "A period that disappears is not a convenient side effect of getting fit. It is information about energy availability, and it deserves a doctor's visit rather than a shrug." },
      { term: "Low energy availability", short: "Not enough fuel left over for the basics.",
        def: "Energy availability is the energy left for your body's core functions after training has taken its share. Push it too low for too long, whether deliberately or accidentally, and the body starts economising on things it treats as optional, including the reproductive system.",
        means: "Under-eating hard enough to stop a cycle is also under-eating hard enough to stall your lifts. Fixing the fuelling usually fixes both." },
      { term: "RED-S", short: "What sustained under-fuelling costs.",
        def: "Relative Energy Deficiency in Sport is the umbrella term for the effects of sustained low energy availability. Beyond menstrual disruption it can affect bone density, immunity, mood, and performance, and it affects men too, just without the visible menstrual warning sign.",
        means: "The menstrual cycle is one of the earliest and clearest warning lights on this dashboard. Losing it is worth acting on early, not once other symptoms pile up." },
      { term: "Bone health", short: "Where lost estrogen shows up years later.",
        def: "Estrogen helps maintain bone density. Extended stretches without a cycle, and therefore without normal estrogen, are linked to lower bone density and a higher risk of stress fractures. The bone built in your teens and twenties is difficult to get back later.",
        means: "Lifting is genuinely good for bone, but it cannot compensate for years of being under-fuelled. Food and the cycle come first." },
      { term: "Perimenopause", short: "The years of transition.",
        def: "Perimenopause is the stretch before periods stop for good, often starting in the forties and lasting several years. Hormones swing unpredictably rather than declining smoothly, so cycles become irregular and symptoms such as poor sleep and hot flushes are common.",
        means: "Strength training becomes more valuable here, not less. It defends the muscle and bone that falling estrogen makes harder to hold onto." },
      { term: "Menopause", short: "Twelve months without a period.",
        def: "Menopause is defined as a full year with no period. Estrogen settles at a low level afterwards, which accelerates loss of bone density and makes muscle harder to maintain.",
        means: "Resistance training and enough protein are among the most effective tools available for protecting bone and muscle through and after this transition." },
      { term: "When to see a doctor", short: "The list worth acting on.",
        def: "Worth getting checked: periods that stop for three months or more, bleeding heavy enough to soak through protection hourly, severe pain that stops you functioning, bleeding between periods, or cycles that change markedly from your normal pattern.",
        means: "This page is background, not diagnosis. Anything on that list is a conversation with a doctor, and your coach only needs to know how it affects your training." },
    ] },
  ];

  // ---- Coach edits to the Anatomy / Science page (overrides + added cards) ----
  // The coach can rewrite any built-in muscle/concept content and add their own
  // cards; athletes see the coach's curated version. Edits are one jsonb blob on
  // the coach row, synced to athletes via the anatomy_edits_for_athlete RPC.
  function anatomySlug(s) { return String(s || "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, ""); }
  function conceptSectionId(kind, groupName) { return kind + ":" + anatomySlug(groupName); }
  function conceptCardId(sid, term) { return sid + "/" + anatomySlug(term); }
  function pickDefined(obj, keys) { const o = {}; keys.forEach((k) => { if (obj[k] != null && obj[k] !== "") o[k] = obj[k]; }); return o; }

  // Which edit blob applies: the coach edits their own; athletes read the copy
  // pulled from their coach. `editable` is true only on the coach-screen mount.
  function getAnatomyEdits(editable) {
    if (editable) return state.trainerData?.anatomyEdits || {};
    return state.clientData?.coachAnatomyEdits || state.trainerData?.anatomyEdits || {};
  }
  // Three concept libraries share one renderer, one editor and one search. Each
  // keeps its own takeaway field so the source data reads naturally.
  const CONCEPT_KINDS = {
    str: { defaults: () => STRENGTH_CONCEPTS, take: "strength", label: "Why it helps strength" },
    nut: { defaults: () => NUTRITION_CONCEPTS, take: "apply",    label: "How to use it" },
    hrm: { defaults: () => HORMONE_CONCEPTS,   take: "means",    label: "What it means for training" },
  };
  function conceptDefaults(kind) { return (CONCEPT_KINDS[kind] || CONCEPT_KINDS.str).defaults(); }
  function conceptTakeOf(kind, item) { return item[(CONCEPT_KINDS[kind] || CONCEPT_KINDS.str).take]; }
  function conceptTakeLabel(kind) { return (CONCEPT_KINDS[kind] || CONCEPT_KINDS.str).label; }

  // ---- Cross-links between the body map and the science shelves ----
  // Reading about a muscle should be one tap from the ideas behind training it.
  // Keyed by movement pattern, since the relevant science is the same for every
  // pressing muscle; a handful of muscles name their own instead.
  const MUSCLE_READ_MORE_BY_PATTERN = {
    push: ["Mechanical tension", "Progressive overload", "Strength is a skill"],
    pull: ["Motor unit recruitment", "Mechanical tension", "Progressive overload"],
    squat: ["Range of motion", "Stretch-shortening cycle", "Progressive overload"],
    hinge: ["Stretch-mediated hypertrophy", "Mechanical tension", "Progressive overload"],
    core: ["Specificity (SAID)", "Mechanical tension", "Progressive overload"],
    isolation: ["Training volume", "Metabolic stress (the pump)", "Proximity to failure"],
  };
  const MUSCLE_READ_MORE = {
    forearms: ["Training volume", "Proximity to failure", "Specificity (SAID)"],
    hamstrings: ["Stretch-mediated hypertrophy", "Muscle spindles", "Range of motion"],
    calves: ["Stretch-shortening cycle", "Muscle fiber types", "Training volume"],
    glutes: ["Range of motion", "Mechanical tension", "Progressive overload"],
  };
  // The reverse direction, only where a concept has a genuinely specific muscle
  // story. Most concepts apply to everything, and chips for those would be noise.
  const CONCEPT_MUSCLES = {
    "Stretch-mediated hypertrophy": ["hamstrings", "chest", "lats"],
    "Muscle spindles": ["hamstrings", "calves"],
    "The stretch reflex": ["calves", "quads"],
    "Stretch-shortening cycle": ["calves", "quads", "glutes"],
    "Metabolic stress (the pump)": ["biceps", "delts-side", "calves"],
    "Range of motion": ["quads", "chest", "lats"],
    "Golgi tendon organs": ["hamstrings", "forearms"],
  };

  // Terms resolve to card ids lazily: the id depends on which group a term sits
  // in, and hard-coding those would rot the moment a card moves.
  let _termIndex = null;
  function termIndex() {
    if (_termIndex) return _termIndex;
    _termIndex = {};
    Object.keys(CONCEPT_KINDS).forEach((kind) => conceptDefaults(kind).forEach((grp) => {
      const sid = conceptSectionId(kind, grp.group);
      grp.items.forEach((it) => {
        _termIndex[it.term] = { kind, sid, cid: conceptCardId(sid, it.term), term: it.term };
      });
    }));
    return _termIndex;
  }
  function muscleReadMore(g) {
    const terms = MUSCLE_READ_MORE[g.id] || MUSCLE_READ_MORE_BY_PATTERN[String(g.pattern || "").toLowerCase()] || [];
    return terms.map((t) => termIndex()[t]).filter(Boolean);
  }
  function muscleReadMoreHtml(g) {
    const links = muscleReadMore(g);
    if (!links.length) return "";
    return `<div class="a-readmore">
      <h4>The science behind it</h4>
      <div class="a-link-chips">${links.map((l) =>
        `<button type="button" class="a-link-chip" data-goto-card="${escapeHtml(l.kind)}|${escapeHtml(l.cid)}">${escapeHtml(l.term)}</button>`).join("")}</div>
    </div>`;
  }
  function conceptMuscleLinksHtml(cardId) {
    const entry = Object.entries(CONCEPT_MUSCLES).find(([term]) => termIndex()[term] && termIndex()[term].cid === cardId);
    if (!entry) return "";
    const ids = entry[1].filter((id) => ANATOMY_BY_ID[id]);
    if (!ids.length) return "";
    return `<div class="a-link-chips a-link-chips-back">
      <span class="a-link-lead">Feel it in</span>
      ${ids.map((id) => `<button type="button" class="a-link-chip" data-goto-muscle="${escapeHtml(id)}">${escapeHtml(ANATOMY_BY_ID[id].name)}</button>`).join("")}
    </div>`;
  }

  // Apply overrides + added cards to a concept library, returning render-ready
  // groups whose items carry a stable id and a normalized `take` takeaway.
  function mergedConceptGroups(kind, edits) {
    const cOv = edits.concepts || {};
    const cAdd = edits.conceptAdds || {};
    return conceptDefaults(kind).map((grp) => {
      const sid = conceptSectionId(kind, grp.group);
      const items = [];
      grp.items.forEach((it) => {
        const cid = conceptCardId(sid, it.term);
        const ov = cOv[cid];
        if (ov && ov.hidden) return;
        const base = { id: cid, term: it.term, short: it.short, def: it.def, take: conceptTakeOf(kind, it) };
        items.push(ov ? { ...base, ...pickDefined(ov, ["term", "short", "def", "take"]), _edited: true } : base);
      });
      (Array.isArray(cAdd[sid]) ? cAdd[sid] : []).forEach((a) =>
        items.push({ id: a.id, term: a.term || "", short: a.short || "", def: a.def || "", take: a.take || "", _added: true }));
      return { id: sid, group: grp.group, tag: grp.tag, icon: grp.icon, accent: grp.accent, items };
    });
  }
  // The unedited default card, for the "reset to default" / diff-on-save path.
  function defaultConceptCard(kind, sid, cid) {
    for (const grp of conceptDefaults(kind)) {
      if (conceptSectionId(kind, grp.group) !== sid) continue;
      for (const it of grp.items) {
        if (conceptCardId(sid, it.term) === cid)
          return { term: it.term, short: it.short, def: it.def, take: conceptTakeOf(kind, it) };
      }
    }
    return null;
  }
  function mergedMuscle(g, edits) {
    const ov = (edits.muscles || {})[g.id] || {};
    const out = { ...g };
    ["does", "why", "warmup", "pairs", "frequency"].forEach((f) => { if (ov[f] != null) out[f] = ov[f]; });
    ["cues", "mistakes", "stretches", "injuries", "anchors", "accessories"].forEach((f) => { if (Array.isArray(ov[f])) out[f] = ov[f]; });
    out._note = ov.note || "";
    out._edited = Object.keys(ov).length > 0;
    return out;
  }

  // All live anatomy mounts (coach view + athlete tab), so edits re-render both.
  const _anatomyRoots = new Set();
  function refreshAnatomy() {
    _anatomyRoots.forEach((root) => { if (root._anatomyRefresh) { try { root._anatomyRefresh(); } catch (e) {} } });
  }
  function saveAnatomyEdits() {
    const t = state.trainerData; if (!t) return;
    t.anatomyEdits = t.anatomyEdits || {};
    localStorage.setItem(KEY_TRAINER, JSON.stringify(t));
    if (window.Cloud?.enabled && t.coachId) {
      window.Cloud.debounce(`coach-anatomy:${t.coachId}`, () => window.Cloud.updateCoachAnatomyEdits(t.coachId, t.anatomyEdits));
    }
    refreshAnatomy();
  }

  // Shared renderer for a collapsible concept library (Strength, Nutrition, …).
  // Groups are already merged (items carry id/term/short/def/take). `editable`
  // adds the coach's per-card Edit and per-group Add controls.
  function conceptGroupsHtml(groups, label, editable) {
    return groups.map((grp) => `<details class="a-cgroup" data-group="${escapeHtml(grp.id)}"${grp.accent ? ` style="--a-accent:${escapeHtml(grp.accent)}"` : ""}>
        <summary class="a-cgroup-sum">
          ${grp.icon ? `<span class="a-cgroup-ico" aria-hidden="true">${dayIconHtml(grp.icon)}</span>` : ""}
          <span class="a-cgroup-title">${escapeHtml(grp.group)}</span>
          <span class="a-cgroup-meta">
            <span class="a-cgroup-tag">${escapeHtml(grp.tag)}</span>
            <span class="a-cgroup-count">${grp.items.length}</span>
            <span class="a-cgroup-chev" aria-hidden="true"></span>
          </span>
        </summary>
        <div class="a-cgrid">
          ${grp.items.map((c) => `<details class="a-concept${c._added ? " is-added" : (c._edited ? " is-edited" : "")}" data-card="${escapeHtml(c.id)}">
            <summary class="a-concept-sum">
              <span class="a-concept-text"><span class="a-concept-term">${escapeHtml(c.term)}</span><span class="a-concept-short">${escapeHtml(c.short)}</span></span>
              <span class="a-concept-chev" aria-hidden="true"></span>
            </summary>
            <div class="a-concept-body">
              <p class="a-concept-def">${escapeHtml(c.def)}</p>
              <p class="a-concept-str"><span class="a-concept-str-label">${escapeHtml(label)}</span>${escapeHtml(c.take)}</p>
              ${conceptMuscleLinksHtml(c.id)}
              ${editable ? `<div class="a-edit-row"><button type="button" class="a-edit-btn" data-edit-card="${escapeHtml(grp.id)}|${escapeHtml(c.id)}">✏️ Edit</button></div>` : ""}
            </div>
          </details>`).join("")}
          ${editable ? `<button type="button" class="a-add-card" data-add-card="${escapeHtml(grp.id)}">＋ Add a card</button>` : ""}
        </div>
      </details>`).join("");
  }

  function strengthConceptsHtml(editable) {
    return `<section class="a-concepts">
      <div class="a-concepts-head">
        <h3>Strength and Hypertrophy Science</h3>
        <p>Plain-language explainers for the ideas behind how training makes you stronger. Pick a topic, then tap any card to open it.</p>
      </div>
      ${conceptGroupsHtml(mergedConceptGroups("str", getAnatomyEdits(editable)), "Why it helps strength", editable)}
    </section>`;
  }

  function nutritionConceptsHtml(editable) {
    return `<section class="a-concepts">
      <div class="a-concepts-head">
        <h3>Nutrition and Body Composition</h3>
        <p>How food turns into fat loss, muscle, and everything in between. Pick a topic, then tap any card to open it.</p>
      </div>
      ${conceptGroupsHtml(mergedConceptGroups("nut", getAnatomyEdits(editable)), conceptTakeLabel("nut"), editable)}
    </section>`;
  }

  function hormoneConceptsHtml(editable) {
    return `<section class="a-concepts">
      <div class="a-concepts-head">
        <h3>Hormones and the Menstrual Cycle</h3>
        <p>What your hormones do to training, appetite and recovery, plus how the menstrual cycle actually works and the signals driving it. Pick a topic, then tap any card to open it.</p>
      </div>
      ${conceptGroupsHtml(mergedConceptGroups("hrm", getAnatomyEdits(editable)), conceptTakeLabel("hrm"), editable)}
      <p class="a-disclaimer">Background reading, not medical advice. Anything that worries you is worth taking to a doctor.</p>
    </section>`;
  }

  // Build the anatomy UI into one container. Static, built once per node.
  function buildAnatomy(root) {
    if (root.dataset.anatomyBuilt) return;
    root.dataset.anatomyBuilt = "1";
    root.classList.add("anatomy"); // enables the column layout + section spacing
    // Only the coach-screen mount is editable; the athlete tab is read-only.
    const editable = !!root.closest("#screen-app");
    // One shelf on screen at a time. Stacking the body map and 58 explainer
    // cards on a single scroll made the page read as three documents in a trench
    // coat; the switcher keeps one interaction model in front of you at once.
    // Search leads: it cuts across all four shelves, so making someone pick a
    // shelf first to reach it had the order backwards.
    root.innerHTML = `
      <div class="a-search-row">
        <span class="a-search-ico" aria-hidden="true">${dayIconHtml("lu:search")}</span>
        <input type="search" class="a-search" data-anatomy-search placeholder="Search muscles and topics" aria-label="Search muscles and topics">
        <button type="button" class="a-search-x hidden" data-search-clear aria-label="Clear search">✕</button>
      </div>
      <div class="a-shelves" role="tablist">
        <button type="button" class="a-shelf-btn active" data-shelf="body" role="tab" aria-selected="true">Body<span class="a-shelf-n" data-count="body"></span></button>
        <button type="button" class="a-shelf-btn" data-shelf="str" role="tab" aria-selected="false">Training<span class="a-shelf-n" data-count="str"></span></button>
        <button type="button" class="a-shelf-btn" data-shelf="nut" role="tab" aria-selected="false">Fuel<span class="a-shelf-n" data-count="nut"></span></button>
        <button type="button" class="a-shelf-btn" data-shelf="hrm" role="tab" aria-selected="false">Hormones<span class="a-shelf-n" data-count="hrm"></span></button>
      </div>
      <div class="a-results hidden" data-anatomy-results></div>
      <div class="a-shelf" data-pane="body">
        <p class="anatomy-intro">Tap a muscle on the body or in the list to see what it does, how to train it, and example lifts.${editable ? " Tap ✏️ Edit on any card to rewrite it or add your own." : ""}</p>
        <div class="anatomy-toggle" role="tablist">
          <button type="button" class="a-view-btn active" data-view="front">Front</button>
          <button type="button" class="a-view-btn" data-view="back">Back</button>
        </div>
        <div class="anatomy-layout">
          <div class="anatomy-figure">${anatomyFigureSvg("front")}${anatomyFigureSvg("back")}</div>
          <div class="anatomy-side">
            <div class="anatomy-list" data-anatomy-list></div>
            <div class="anatomy-detail" data-anatomy-detail>
              <div class="anatomy-detail-empty">Select a muscle group to see the details.</div>
            </div>
          </div>
        </div>
      </div>
      <div class="a-shelf hidden" data-pane="str"></div>
      <div class="a-shelf hidden" data-pane="nut"></div>
      <div class="a-shelf hidden" data-pane="hrm"></div>`;

    const listEl = root.querySelector("[data-anatomy-list]");
    const detailEl = root.querySelector("[data-anatomy-detail]");
    const paneEl = (k) => root.querySelector(`[data-pane="${k}"]`);
    const searchEl = root.querySelector("[data-anatomy-search]");
    const resultsEl = root.querySelector("[data-anatomy-results]");
    let view = "front";
    let selected = null;
    let shelf = "body";

    function renderConcepts() {
      paneEl("str").innerHTML = strengthConceptsHtml(editable);
      paneEl("nut").innerHTML = nutritionConceptsHtml(editable);
      paneEl("hrm").innerHTML = hormoneConceptsHtml(editable);
      const count = (kind) => mergedConceptGroups(kind, getAnatomyEdits(editable))
        .reduce((n, g) => n + g.items.length, 0);
      root.querySelector('[data-count="body"]').textContent = ANATOMY_GROUPS.length;
      ["str", "nut", "hrm"].forEach((k) => { root.querySelector(`[data-count="${k}"]`).textContent = count(k); });
    }
    function setShelf(next) {
      shelf = next;
      root.querySelectorAll(".a-shelf-btn").forEach((b) => {
        const on = b.dataset.shelf === next;
        b.classList.toggle("active", on);
        b.setAttribute("aria-selected", String(on));
      });
      root.querySelectorAll("[data-pane]").forEach((p) => p.classList.toggle("hidden", p.dataset.pane !== next));
    }
    function renderList() {
      listEl.innerHTML = ANATOMY_VIEW_GROUPS[view].map((id) => {
        const g = ANATOMY_BY_ID[id];
        return `<button type="button" class="a-chip${id === selected ? " selected" : ""}" data-muscle="${id}">${escapeHtml(g.name)}</button>`;
      }).join("");
    }
    function highlight() {
      root.querySelectorAll(".a-zone.selected, .a-chip.selected").forEach((el) => el.classList.remove("selected"));
      if (!selected) return;
      root.querySelectorAll(`.a-svg[data-fig="${view}"] .a-zone[data-muscle="${selected}"], .a-chip[data-muscle="${selected}"]`)
        .forEach((el) => el.classList.add("selected"));
    }
    function renderDetail() {
      if (!selected) return;
      const g = ANATOMY_BY_ID[selected];
      if (g) detailEl.innerHTML = anatomyDetailHtml(mergedMuscle(g, getAnatomyEdits(editable)), editable);
    }
    function select(id) {
      if (!ANATOMY_BY_ID[id]) return;
      selected = id;
      renderDetail();
      highlight();
    }
    function setView(next) {
      if (next === view) return;
      view = next;
      root.querySelectorAll(".a-view-btn").forEach((b) => b.classList.toggle("active", b.dataset.view === view));
      root.querySelectorAll(".a-svg").forEach((s) => s.classList.toggle("hidden", s.dataset.fig !== view));
      // Keep the selection if the group also lives in the new view, else clear.
      if (selected && !ANATOMY_VIEW_GROUPS[view].includes(selected)) {
        selected = null;
        detailEl.innerHTML = '<div class="anatomy-detail-empty">Select a muscle group to see the details.</div>';
      }
      renderList();
      highlight();
    }

    // ---- Search across both halves of the library ----
    // 58 cards behind 13 collapsed groups is unfindable by scrolling, so one
    // box searches muscles and explainers together and jumps you into the shelf.
    function searchIndex() {
      const edits = getAnatomyEdits(editable);
      const rows = ANATOMY_GROUPS.map((g0) => {
        const g = mergedMuscle(g0, edits);
        return { kind: "muscle", id: g.id, title: g.name, sub: g.sub, where: g.pattern,
          hay: [g.name, g.sub, g.does, g.why, ...(g.anchors || []), ...(g.accessories || [])].join(" ").toLowerCase() };
      });
      ["str", "nut", "hrm"].forEach((kind) => mergedConceptGroups(kind, edits).forEach((grp) => grp.items.forEach((c) => {
        rows.push({ kind, id: c.id, title: c.term, sub: c.short, where: grp.group, accent: grp.accent,
          hay: [c.term, c.short, c.def, c.take, grp.group, grp.tag].join(" ").toLowerCase() });
      })));
      return rows;
    }
    function runSearch(qRaw) {
      const q = String(qRaw || "").trim().toLowerCase();
      root.querySelector("[data-search-clear]").classList.toggle("hidden", !q);
      if (q.length < 2) {
        resultsEl.classList.add("hidden");
        root.querySelector(`[data-pane="${shelf}"]`).classList.remove("hidden");
        return;
      }
      root.querySelectorAll("[data-pane]").forEach((p) => p.classList.add("hidden"));
      resultsEl.classList.remove("hidden");
      // Title matches first: searching "calves" should not bury Calves under
      // every card that merely mentions them.
      const hits = searchIndex().filter((r) => r.hay.includes(q))
        .sort((a, b) => (b.title.toLowerCase().includes(q) ? 1 : 0) - (a.title.toLowerCase().includes(q) ? 1 : 0));
      if (!hits.length) {
        resultsEl.innerHTML = `<p class="a-noresults">Nothing matches “${escapeHtml(qRaw)}”.</p>`;
        return;
      }
      const label = { muscle: "Body", str: "Training", nut: "Fuel", hrm: "Hormones" };
      resultsEl.innerHTML = `<p class="a-results-n">${hits.length} result${hits.length === 1 ? "" : "s"}</p>` +
        hits.map((r) => `<button type="button" class="a-result"${r.accent ? ` style="--a-accent:${escapeHtml(r.accent)}"` : ""} ${
          r.kind === "muscle" ? `data-goto-muscle="${escapeHtml(r.id)}"` : `data-goto-card="${escapeHtml(r.kind)}|${escapeHtml(r.id)}"`}>
          <span class="a-result-main">
            <span class="a-result-title">${escapeHtml(r.title)}</span>
            <span class="a-result-sub">${escapeHtml(r.sub || "")}</span>
          </span>
          <span class="a-result-where">${escapeHtml(label[r.kind])} · ${escapeHtml(r.where || "")}</span>
        </button>`).join("");
    }
    function clearSearch() {
      searchEl.value = "";
      runSearch("");
    }
    // Landing on a card from a search hit or a cross-link: open its group and
    // the card itself, then bring it into view.
    function gotoCard(kind, cid) {
      clearSearch();
      setShelf(kind);
      const card = paneEl(kind).querySelector(`[data-card="${CSS.escape(cid)}"]`);
      if (!card) return;
      const grp = card.closest(".a-cgroup");
      if (grp) grp.open = true;
      card.open = true;
      card.classList.add("a-flash");
      setTimeout(() => card.classList.remove("a-flash"), 1200);
      requestAnimationFrame(() => card.scrollIntoView({ block: "center", behavior: "smooth" }));
    }
    function gotoMuscle(id) {
      clearSearch();
      setShelf("body");
      // The muscle may live on the face of the body we are not looking at.
      if (!ANATOMY_VIEW_GROUPS[view].includes(id)) {
        const other = view === "front" ? "back" : "front";
        if (ANATOMY_VIEW_GROUPS[other].includes(id)) setView(other);
      }
      select(id);
      requestAnimationFrame(() => detailEl.scrollIntoView({ block: "nearest", behavior: "smooth" }));
    }

    root.querySelectorAll(".a-shelf-btn").forEach((b) =>
      b.addEventListener("click", () => { clearSearch(); setShelf(b.dataset.shelf); }));
    searchEl.addEventListener("input", () => runSearch(searchEl.value));
    root.querySelector("[data-search-clear]").addEventListener("click", () => { clearSearch(); searchEl.focus(); });

    root.querySelectorAll(".a-view-btn").forEach((b) =>
      b.addEventListener("click", () => setView(b.dataset.view)));
    root.addEventListener("click", (e) => {
      const gotoM = e.target.closest("[data-goto-muscle]");
      if (gotoM && root.contains(gotoM)) { gotoMuscle(gotoM.dataset.gotoMuscle); return; }
      const gotoC = e.target.closest("[data-goto-card]");
      if (gotoC && root.contains(gotoC)) { const [k, cid] = gotoC.dataset.gotoCard.split("|"); gotoCard(k, cid); return; }
      const editCard = e.target.closest("[data-edit-card]");
      if (editCard && root.contains(editCard)) { const [sid, cid] = editCard.dataset.editCard.split("|"); openConceptCardEditor(sid, cid); return; }
      const addCard = e.target.closest("[data-add-card]");
      if (addCard && root.contains(addCard)) { openAddConceptCard(addCard.dataset.addCard); return; }
      const editMus = e.target.closest("[data-edit-muscle]");
      if (editMus && root.contains(editMus)) { openMuscleEditor(editMus.dataset.editMuscle); return; }
      const zone = e.target.closest(".a-zone, .a-chip");
      if (zone && root.contains(zone)) select(zone.dataset.muscle);
    });

    // Let coach edits re-render this mount's concepts + open muscle in place.
    root._anatomyRefresh = () => { renderConcepts(); renderDetail(); };
    _anatomyRoots.add(root);
    renderConcepts();
    renderList();
  }
  // Build every anatomy mount point once at boot (coach view + athlete tab).
  function initAnatomyLibrary() {
    document.querySelectorAll("[data-anatomy-root]").forEach(buildAnatomy);
  }

  // -------- Coach anatomy/concept editors (coach-screen only) --------
  function conceptKindOf(sid) { const k = String(sid).split(":")[0]; return CONCEPT_KINDS[k] ? k : "str"; }
  function findMergedCard(sid, cid) {
    const kind = conceptKindOf(sid);
    const grp = mergedConceptGroups(kind, state.trainerData?.anatomyEdits || {}).find((g) => g.id === sid);
    return { kind, card: grp && grp.items.find((c) => c.id === cid) };
  }
  function conceptEditorBody(card, takeLabel) {
    return `<div class="a-editor">
      <label>Title<input type="text" id="ace-term" value="${escapeHtml(card.term || "")}" placeholder="e.g. Progressive overload" /></label>
      <label>One-line summary<input type="text" id="ace-short" value="${escapeHtml(card.short || "")}" placeholder="The short version, shown on the closed card" /></label>
      <label>Explanation<textarea id="ace-def" rows="5" placeholder="The main explanation.">${escapeHtml(card.def || "")}</textarea></label>
      <label>${escapeHtml(takeLabel)}<textarea id="ace-take" rows="4" placeholder="The practical takeaway.">${escapeHtml(card.take || "")}</textarea></label>
    </div>`;
  }
  function readConceptEditor() {
    return {
      term: $("#ace-term").value.trim(), short: $("#ace-short").value.trim(),
      def: $("#ace-def").value.trim(), take: $("#ace-take").value.trim(),
    };
  }
  function openConceptCardEditor(sid, cid) {
    const { kind, card } = findMergedCard(sid, cid);
    if (!card) return;
    const takeLabel = conceptTakeLabel(kind);
    const actions = [{ label: "Save", className: "btn btn-primary", onClick: () => {
      const v = readConceptEditor();
      if (!v.term) { toast("Give the card a title."); return; }
      const t = state.trainerData; t.anatomyEdits = t.anatomyEdits || {};
      if (card._added) {
        const e = ((t.anatomyEdits.conceptAdds || {})[sid] || []).find((x) => x.id === cid);
        if (e) Object.assign(e, v);
      } else {
        const d = defaultConceptCard(kind, sid, cid) || {};
        const ov = {};
        ["term", "short", "def", "take"].forEach((k) => { if (v[k] !== (d[k] || "")) ov[k] = v[k]; });
        t.anatomyEdits.concepts = t.anatomyEdits.concepts || {};
        if (Object.keys(ov).length) t.anatomyEdits.concepts[cid] = ov;
        else delete t.anatomyEdits.concepts[cid];
      }
      saveAnatomyEdits(); closeModal(); toast("Saved");
    } }];
    if (card._added) {
      actions.push({ label: "Delete card", className: "btn btn-ghost", onClick: () => {
        const t = state.trainerData, arr = (t.anatomyEdits.conceptAdds || {})[sid];
        if (arr) { t.anatomyEdits.conceptAdds[sid] = arr.filter((x) => x.id !== cid); if (!t.anatomyEdits.conceptAdds[sid].length) delete t.anatomyEdits.conceptAdds[sid]; }
        saveAnatomyEdits(); closeModal(); toast("Card deleted");
      } });
    } else if (card._edited) {
      actions.push({ label: "Reset to default", className: "btn btn-ghost", onClick: () => {
        const t = state.trainerData; if (t.anatomyEdits.concepts) delete t.anatomyEdits.concepts[cid];
        saveAnatomyEdits(); closeModal(); toast("Reset to default");
      } });
    }
    actions.push({ label: "Cancel", className: "btn btn-ghost", onClick: closeModal });
    openModal({ title: "Edit card", body: conceptEditorBody(card, takeLabel), actions });
  }
  function openAddConceptCard(sid) {
    const kind = conceptKindOf(sid);
    const takeLabel = conceptTakeLabel(kind);
    openModal({
      title: "Add a card",
      body: conceptEditorBody({}, takeLabel),
      actions: [
        { label: "Add card", className: "btn btn-primary", onClick: () => {
          const v = readConceptEditor();
          if (!v.term) { toast("Give the card a title."); return; }
          const t = state.trainerData; t.anatomyEdits = t.anatomyEdits || {};
          t.anatomyEdits.conceptAdds = t.anatomyEdits.conceptAdds || {};
          (t.anatomyEdits.conceptAdds[sid] || (t.anatomyEdits.conceptAdds[sid] = [])).push({ id: "add-" + uid(), ...v });
          saveAnatomyEdits(); closeModal(); toast("Card added");
        } },
        { label: "Cancel", className: "btn btn-ghost", onClick: closeModal },
      ],
    });
  }

  const MUSCLE_TEXT_FIELDS = [
    ["does", "What it does", "textarea"],
    ["why", "Why it matters", "textarea"],
    ["warmup", "Warm-up", "input"],
    ["pairs", "Pairs with", "input"],
    ["frequency", "Frequency", "input"],
  ];
  const MUSCLE_LIST_FIELDS = [
    ["cues", "Coaching cues"],
    ["mistakes", "Common mistakes"],
    ["stretches", "Stretches"],
    ["injuries", "Common injuries"],
    ["anchors", "Example lifts (main)"],
    ["accessories", "Example lifts (accessory)"],
  ];
  function openMuscleEditor(muscleId) {
    const g0 = ANATOMY_BY_ID[muscleId]; if (!g0) return;
    const m = mergedMuscle(g0, state.trainerData?.anatomyEdits || {});
    const textHtml = MUSCLE_TEXT_FIELDS.map(([f, label, kind]) => `<label>${escapeHtml(label)}${
      kind === "input"
        ? `<input type="text" id="ame-${f}" value="${escapeHtml(m[f] || "")}" />`
        : `<textarea id="ame-${f}" rows="3">${escapeHtml(m[f] || "")}</textarea>`
    }</label>`).join("");
    const listHtml = MUSCLE_LIST_FIELDS.map(([f, label]) => `<label>${escapeHtml(label)} <span class="a-editor-hint">one per line</span><textarea id="ame-${f}" rows="3">${escapeHtml((m[f] || []).join("\n"))}</textarea></label>`).join("");
    const body = `<div class="a-editor">
      <p class="a-editor-lead">Editing <strong>${escapeHtml(g0.name)}</strong>. Leave a field as-is to keep the built-in text.</p>
      ${textHtml}
      ${listHtml}
      <label>Coach note <span class="a-editor-hint">shown to athletes, in addition to the above</span><textarea id="ame-note" rows="3" placeholder="Anything extra you want your athletes to see here.">${escapeHtml(m._note || "")}</textarea></label>
    </div>`;
    const actions = [{ label: "Save", className: "btn btn-primary", onClick: () => {
      const ov = {};
      MUSCLE_TEXT_FIELDS.forEach(([f]) => { const v = $(`#ame-${f}`).value.trim(); if (v !== (g0[f] || "")) ov[f] = v; });
      MUSCLE_LIST_FIELDS.forEach(([f]) => {
        const arr = $(`#ame-${f}`).value.split("\n").map((s) => s.trim()).filter(Boolean);
        if (JSON.stringify(arr) !== JSON.stringify(g0[f] || [])) ov[f] = arr;
      });
      const note = $("#ame-note").value.trim(); if (note) ov.note = note;
      const t = state.trainerData; t.anatomyEdits = t.anatomyEdits || {}; t.anatomyEdits.muscles = t.anatomyEdits.muscles || {};
      if (Object.keys(ov).length) t.anatomyEdits.muscles[muscleId] = ov;
      else delete t.anatomyEdits.muscles[muscleId];
      saveAnatomyEdits(); closeModal(); toast("Saved");
    } }];
    if (m._edited) {
      actions.push({ label: "Reset to default", className: "btn btn-ghost", onClick: () => {
        const t = state.trainerData; if (t.anatomyEdits.muscles) delete t.anatomyEdits.muscles[muscleId];
        saveAnatomyEdits(); closeModal(); toast("Reset to default");
      } });
    }
    actions.push({ label: "Cancel", className: "btn btn-ghost", onClick: closeModal });
    openModal({ title: "Edit muscle", body, actions });
  }

  // Rebuild a single shared <datalist> (respecting the coach's hidden list) and
  // return its id so type-to-add inputs can point at it via `list=`.
  function ensureExerciseDatalist() {
    const hidden = state.trainerData.hiddenExercises || [];
    let dl = document.getElementById("ex-name-datalist");
    if (!dl) {
      dl = document.createElement("datalist");
      dl.id = "ex-name-datalist";
      document.body.appendChild(dl);
    }
    const names = [...new Set([...ALL_EXERCISE_NAMES, ...customExerciseList().map((c) => c.name)])]
      .sort((a, b) => a.localeCompare(b));
    dl.innerHTML = names
      .filter((n) => !hidden.includes(n))
      .map((n) => `<option value="${escapeHtml(n)}"></option>`)
      .join("");
    return "ex-name-datalist";
  }

  // Coach-added custom exercises. Guarded for the athlete side, where
  // trainerData may not exist.
  function customExerciseList() {
    return state.trainerData?.customExercises || [];
  }
  function isCustomExercise(name) {
    return customExerciseList().some((c) => c.name === name);
  }

  // Built-in library merged with the coach's custom exercises. Customs filed
  // under a built-in category append to it; unknown categories become new ones.
  function fullExerciseLibrary() {
    const cats = EXERCISE_LIBRARY.map((c) => ({ cat: c.cat, ex: [...c.ex] }));
    for (const ce of customExerciseList()) {
      if (!ce?.name) continue;
      const cat = ce.cat || "My Exercises";
      let entry = cats.find((c) => c.cat === cat);
      if (!entry) { entry = { cat, ex: [] }; cats.push(entry); }
      if (!entry.ex.includes(ce.name)) entry.ex.push(ce.name);
    }
    return cats;
  }

  // Coach's custom category order (array of cat names, persisted in trainerData).
  // Categories not in the saved order (e.g. added in an app update) keep their
  // built-in position at the end.
  function orderedExerciseLibrary() {
    const lib = fullExerciseLibrary();
    const saved = Array.isArray(state.trainerData.exCatOrder) ? state.trainerData.exCatOrder : [];
    const byCat = new Map(lib.map((c) => [c.cat, c]));
    const out = [];
    const seen = new Set();
    for (const cat of saved) {
      const entry = byCat.get(cat);
      if (entry && !seen.has(cat)) { out.push(entry); seen.add(cat); }
    }
    for (const entry of lib) if (!seen.has(entry.cat)) out.push(entry);
    return out;
  }

  function addCustomExercise(rawName, rawCat) {
    const name = (rawName || "").trim();
    const cat = (rawCat || "").trim() || "My Exercises";
    if (!name) { toast("Enter an exercise name"); return false; }
    const clash = fullExerciseLibrary().some((c) => c.ex.some((e) => e.toLowerCase() === name.toLowerCase()));
    if (clash) {
      const hidden = state.trainerData.hiddenExercises || [];
      toast(hidden.some((h) => h.toLowerCase() === name.toLowerCase())
        ? "Already in the library. Check the Hidden tab"
        : "That exercise is already in the library");
      return false;
    }
    if (!Array.isArray(state.trainerData.customExercises)) state.trainerData.customExercises = [];
    state.trainerData.customExercises.push({ name, cat });
    _expandedExCats.add(cat); // show the new exercise right away
    saveTrainer();
    ensureExerciseDatalist();
    renderExLibrary($("#ex-library-search")?.value || "");
    renderSidebarLibrary($("#ex-lib-sb-search")?.value || "");
    toast(`Added ${name} to the library 💪`);
    return true;
  }

  function deleteCustomExercise(name) {
    if (!window.confirm(`Remove "${name}" from your library? Days already using it keep it.`)) return;
    state.trainerData.customExercises = customExerciseList().filter((c) => c.name !== name);
    saveTrainer();
    ensureExerciseDatalist();
    renderExLibrary($("#ex-library-search")?.value || "");
    renderSidebarLibrary($("#ex-lib-sb-search")?.value || "");
    toast("Custom exercise removed");
  }

  // Wire one "+ Custom exercise" button/form pair (sidebar and modal each have
  // one; ids share a prefix: `${prefix}-btn`, `-form`, `-name`, `-cat`,
  // `-newcat`, `-save`, `-cancel`).
  function setupExAddForm(prefix) {
    const btn = $(`#${prefix}-btn`), form = $(`#${prefix}-form`),
          nameEl = $(`#${prefix}-name`), catEl = $(`#${prefix}-cat`),
          newCatEl = $(`#${prefix}-newcat`), saveEl = $(`#${prefix}-save`),
          cancelEl = $(`#${prefix}-cancel`);
    if (!btn || !form) return;
    const close = () => { hide(form); show(btn); };
    btn.addEventListener("click", () => {
      catEl.innerHTML = orderedExerciseLibrary()
        .map(({ cat }) => `<option value="${escapeHtml(cat)}">${escapeHtml(cat)}</option>`)
        .join("") + `<option value="__new__">➕ New category…</option>`;
      nameEl.value = "";
      newCatEl.value = "";
      hide(newCatEl);
      show(form); hide(btn);
      nameEl.focus();
    });
    catEl.addEventListener("change", () => {
      if (catEl.value === "__new__") { show(newCatEl); newCatEl.focus(); }
      else hide(newCatEl);
    });
    const submit = () => {
      const cat = catEl.value === "__new__" ? newCatEl.value.trim() : catEl.value;
      if (catEl.value === "__new__" && !cat) { toast("Enter a category name"); newCatEl.focus(); return; }
      if (addCustomExercise(nameEl.value, cat)) close();
    };
    saveEl.addEventListener("click", submit);
    cancelEl.addEventListener("click", close);
    [nameEl, newCatEl].forEach((el) => el.addEventListener("keydown", (e) => {
      if (e.key === "Enter") { e.preventDefault(); submit(); }
      if (e.key === "Escape") close();
    }));
  }
  function moveExCategory(cat, dir) {
    const order = orderedExerciseLibrary().map((c) => c.cat);
    const i = order.indexOf(cat);
    const j = i + dir;
    if (i === -1 || j < 0 || j >= order.length) return;
    [order[i], order[j]] = [order[j], order[i]];
    state.trainerData.exCatOrder = order;
    saveTrainer();
    renderExLibrary($("#ex-library-search")?.value || "");
    renderSidebarLibrary($("#ex-lib-sb-search")?.value || "");
  }

  // Which categories are expanded (session-only — everything starts collapsed).
  // Shared by the modal library and the sidebar library.
  const _expandedExCats = new Set();
  function toggleExCategory(cat) {
    if (_expandedExCats.has(cat)) _expandedExCats.delete(cat);
    else _expandedExCats.add(cat);
    renderExLibrary($("#ex-library-search")?.value || "");
    renderSidebarLibrary($("#ex-lib-sb-search")?.value || "");
  }

  function openExLibrary(day, rerenderFn, opts) {
    _exLibraryTarget = day ? { day, rerenderFn, opts: opts || {} } : null;
    // The athlete's own-session builder reuses this drawer, so it still hides
    // the coach-only "add to library" control — that writes the coach's
    // exercise library, which an athlete has no business (or permission) editing.
    // Free-text names still get in via the builder's type-to-add.
    $("#ex-library-overlay").classList.toggle("athlete-mode", !!opts?.athlete);
    show($("#ex-library-overlay"));
    // The drawer is its own nav level: Back closes it instead of backing out of
    // the day underneath and leaving the library floating over the picker.
    Nav.push(closeExLibrary);
    renderExLibrary($("#ex-library-search").value || "");
    setTimeout(() => $("#ex-library-search").focus(), 100);
  }
  function closeExLibrary() { hide($("#ex-library-overlay")); _exLibraryTarget = null; }
  // Every close path goes through Nav so the level pushed on open is popped
  // with it. Closing without popping would leave a stale entry and the next
  // Back press would silently do nothing.
  function dismissExLibrary() { Nav.back(closeExLibrary); }

  // Athlete "add an exercise on the fly" — same library drawer, but picks land
  // in the athlete's progress (addedExercises) instead of the coach's program.
  function openAthleteExLibrary(day) {
    // Athlete-built sessions take the pick into the day itself; program days
    // park it in progress.addedExercises so the coach's weeks stay untouched.
    _exLibraryTarget = { onAdd: (name) => (isOwnDay(day) ? addOwnExercise(day, name) : addAthleteExercise(day, name)) };
    $("#ex-library-overlay").classList.add("athlete-mode"); // hides coach-only "custom exercise"
    show($("#ex-library-overlay"));
    Nav.push(closeExLibrary); // Back closes the drawer, not the day behind it

    renderExLibrary($("#ex-library-search").value || "");
    setTimeout(() => $("#ex-library-search").focus(), 100);
  }
  function addAthleteExercise(day, name) {
    const p = state.clientData.progress;
    if (!p.addedExercises) p.addedExercises = {};
    const list = p.addedExercises[day.id] || (p.addedExercises[day.id] = []);
    if (list.length >= MAX_ADDED_PER_DAY) {
      toast(`You can add up to ${MAX_ADDED_PER_DAY} extra exercises per day.`);
      return;
    }
    const ex = makeExercise({ name });
    ex.addedByAthlete = true;
    ex.addedAt = Date.now();
    list.push(ex);
    saveClient();
    toast(`Added ${name}`);
    if (list.length >= MAX_ADDED_PER_DAY) dismissExLibrary();
    renderWorkoutDetailUI();
  }
  function removeAthleteExercise(day, ex) {
    const p = state.clientData.progress;
    const list = p.addedExercises?.[day.id];
    if (!list) return;
    const hasLog = p.exerciseLogs?.[ex.id]?.length;
    if (hasLog && !window.confirm(`Remove "${ex.name}" and the sets you logged for it?`)) return;
    p.addedExercises[day.id] = list.filter((e) => e.id !== ex.id);
    if (!p.addedExercises[day.id].length) delete p.addedExercises[day.id];
    if (p.exerciseLogs?.[ex.id]) delete p.exerciseLogs[ex.id]; // drop its orphaned log
    saveClient();
    renderWorkoutDetailUI();
  }
  function renderExLibrary(filter) {
    const q = filter.toLowerCase().trim();
    const body = $("#ex-library-body");
    const hidden = state.trainerData.hiddenExercises || [];
    const cats = orderedExerciseLibrary();
    let html = "";
    cats.forEach(({ cat, ex }, idx) => {
      let items = ex.filter((e) => !hidden.includes(e));
      if (q) items = items.filter((e) => e.toLowerCase().includes(q));
      if (!items.length) return;
      // Searching force-expands every matching category so results stay visible.
      const open = !!q || _expandedExCats.has(cat);
      html += `<div class="ex-cat-header${open ? " open" : ""}" data-cat="${escapeHtml(cat)}">
        <span class="ex-cat-caret">${open ? "▾" : "▸"}</span>
        <span class="ex-cat-title">${escapeHtml(cat)}</span>
        <span class="ex-cat-count">${items.length}</span>
        ${q ? "" : `<span class="ex-cat-move">
          <button type="button" class="ex-cat-move-btn" data-move="-1" data-cat="${escapeHtml(cat)}" title="Move category up"${idx === 0 ? " disabled" : ""}>↑</button>
          <button type="button" class="ex-cat-move-btn" data-move="1" data-cat="${escapeHtml(cat)}" title="Move category down"${idx === cats.length - 1 ? " disabled" : ""}>↓</button>
        </span>`}
      </div>`;
      if (open) html += items.map((name) => {
        const entry = demoEntryForName(name);
        const thumb = entry
          ? `<img class="ex-lib-thumb" src="${demoImgUrl(entry.i, 0)}" alt="" loading="lazy" draggable="false" />`
          : `<span class="ex-lib-thumb ex-lib-thumb-none">💪</span>`;
        return `<div class="ex-lib-item" draggable="true" data-exname="${escapeHtml(name)}">${thumb}<span class="ex-lib-item-name">${escapeHtml(name)}</span></div>`;
      }).join("");
    });
    body.innerHTML = html || '<div class="ex-lib-empty">No exercises found.</div>';
    body.querySelectorAll(".ex-cat-header").forEach((h) => {
      h.addEventListener("click", () => { if (!q) toggleExCategory(h.dataset.cat); });
    });
    body.querySelectorAll(".ex-cat-move-btn").forEach((btn) => {
      btn.addEventListener("click", (e) => {
        e.stopPropagation();
        moveExCategory(btn.dataset.cat, Number(btn.dataset.move));
      });
    });
    body.querySelectorAll(".ex-lib-item").forEach((item) => {
      item.addEventListener("dragstart", (e) => {
        e.dataTransfer.setData("text/ex-name", item.dataset.exname);
        e.dataTransfer.effectAllowed = "copy";
      });
      // Tap-to-add — drag-and-drop doesn't work on touch devices, so this is
      // the primary path on mobile (where the library opens as this modal
      // instead of the persistent sidebar).
      item.addEventListener("click", () => {
        if (!_exLibraryTarget) return;
        // Athlete flow: hand the name off to the caller (adds to their progress).
        if (_exLibraryTarget.onAdd) { _exLibraryTarget.onAdd(item.dataset.exname); return; }
        const { day, rerenderFn, opts } = _exLibraryTarget;
        const cap = opts?.cap;
        if (cap && day.exercises.length >= cap) {
          toast(`A session holds up to ${cap} exercises.`);
          dismissExLibrary();
          return;
        }
        day.exercises.push(makeExercise({ name: item.dataset.exname }));
        saveEditor();
        toast(`Added ${item.dataset.exname}`);
        if (cap && day.exercises.length >= cap) dismissExLibrary();
        rerenderFn();
      });
    });
  }

  // -------- Persistent Library Sidebar --------
  // Which tab is showing: "active" (draggable library) or "hidden" (parked exercises).
  let _libSbTab = "active";

  function hideExercise(name) {
    if (!Array.isArray(state.trainerData.hiddenExercises)) state.trainerData.hiddenExercises = [];
    if (!state.trainerData.hiddenExercises.includes(name)) {
      state.trainerData.hiddenExercises.push(name);
      saveTrainer();
    }
    renderSidebarLibrary($("#ex-lib-sb-search")?.value || "");
  }
  function unhideExercise(name) {
    state.trainerData.hiddenExercises = (state.trainerData.hiddenExercises || []).filter((n) => n !== name);
    saveTrainer();
    renderSidebarLibrary($("#ex-lib-sb-search")?.value || "");
  }

  function renderSidebarLibrary(filter) {
    const q = (filter || "").toLowerCase().trim();
    const body = $("#ex-lib-sb-body");
    if (!body) return;
    const hidden = state.trainerData.hiddenExercises || [];
    const showingHidden = _libSbTab === "hidden";

    // Keep the tab UI + hint in sync with the active tab.
    $$(".ex-lib-sb-tab").forEach((t) => t.classList.toggle("active", t.dataset.libTab === _libSbTab));
    const countEl = $("#ex-lib-hidden-count");
    if (countEl) countEl.textContent = hidden.length ? `(${hidden.length})` : "";
    const hintEl = $("#ex-lib-sb-hint");
    if (hintEl) hintEl.textContent = showingHidden ? "Tap ↩ to restore" : "Drag onto a day";

    body.innerHTML = "";
    const cats = orderedExerciseLibrary();
    cats.forEach(({ cat, ex }, idx) => {
      let items = ex.filter((e) => (showingHidden ? hidden.includes(e) : !hidden.includes(e)));
      if (q) items = items.filter((e) => e.toLowerCase().includes(q));
      if (!items.length) return;
      // Searching force-expands every matching category so results stay visible.
      const open = !!q || _expandedExCats.has(cat);
      const catEl = document.createElement("div");
      catEl.className = "ex-lib-sb-cat" + (open ? " open" : "");

      const caret = document.createElement("span");
      caret.className = "ex-cat-caret";
      caret.textContent = open ? "▾" : "▸";
      catEl.appendChild(caret);

      const title = document.createElement("span");
      title.className = "ex-cat-title";
      title.textContent = cat;
      catEl.appendChild(title);

      const count = document.createElement("span");
      count.className = "ex-cat-count";
      count.textContent = items.length;
      catEl.appendChild(count);

      // Reorder arrows: active tab only, and not while searching (the visible
      // neighbours wouldn't match the real order).
      if (!showingHidden && !q) {
        const moveWrap = document.createElement("span");
        moveWrap.className = "ex-cat-move";
        [["-1", "↑", "Move category up", idx === 0], ["1", "↓", "Move category down", idx === cats.length - 1]].forEach(([dir, sym, tip, atEdge]) => {
          const mb = document.createElement("button");
          mb.type = "button";
          mb.className = "ex-cat-move-btn";
          mb.textContent = sym;
          mb.title = tip;
          mb.disabled = atEdge;
          mb.addEventListener("click", (e) => { e.stopPropagation(); moveExCategory(cat, Number(dir)); });
          moveWrap.appendChild(mb);
        });
        catEl.appendChild(moveWrap);
      }

      catEl.addEventListener("click", () => { if (!q) toggleExCategory(cat); });
      body.appendChild(catEl);
      if (!open) return;
      items.forEach((name) => {
        const item = document.createElement("div");
        item.className = "ex-lib-sb-item" + (showingHidden ? " is-hidden-row" : "");

        const entry = demoEntryForName(name);
        const thumb = document.createElement(entry ? "img" : "span");
        thumb.className = "ex-lib-thumb" + (entry ? "" : " ex-lib-thumb-none");
        if (entry) { thumb.src = demoImgUrl(entry.i, 0); thumb.loading = "lazy"; thumb.alt = ""; thumb.draggable = false; }
        else thumb.textContent = "💪";
        item.appendChild(thumb);

        const label = document.createElement("span");
        label.className = "ex-lib-sb-item-name";
        label.textContent = name;
        item.appendChild(label);

        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "ex-lib-sb-actbtn";
        if (showingHidden) {
          btn.textContent = "↩";
          btn.title = "Restore to library";
          btn.addEventListener("click", (e) => { e.stopPropagation(); unhideExercise(name); });
        } else if (isCustomExercise(name)) {
          btn.textContent = "🗑";
          btn.title = "Delete custom exercise";
          btn.addEventListener("click", (e) => { e.stopPropagation(); deleteCustomExercise(name); });
        } else {
          btn.textContent = "✕";
          btn.title = "Hide from library";
          btn.addEventListener("click", (e) => { e.stopPropagation(); hideExercise(name); });
        }
        item.appendChild(btn);

        // Only active-library rows are drag sources.
        if (!showingHidden) {
          item.draggable = true;
          item.dataset.exname = name;
          item.addEventListener("dragstart", (e) => {
            item.classList.add("dragging-active");
            e.dataTransfer.setData("text/ex-name", name);
            e.dataTransfer.effectAllowed = "copy";
          });
          item.addEventListener("dragend", () => item.classList.remove("dragging-active"));
        }
        body.appendChild(item);
      });
    });
    if (!body.children.length) {
      const msg = showingHidden
        ? (hidden.length ? "No hidden exercises match your search." : "No hidden exercises. Tap ✕ on a library exercise to park it here.")
        : "No exercises found.";
      body.innerHTML = `<div style="padding:1rem;color:var(--muted);font-size:0.82rem">${msg}</div>`;
    }
  }

  function setLibSbTab(tab) {
    _libSbTab = tab === "hidden" ? "hidden" : "active";
    renderSidebarLibrary($("#ex-lib-sb-search")?.value || "");
  }

  function showLibSidebar() {
    const layout = document.querySelector(".coach-layout");
    if (layout) layout.classList.add("show-lib-sidebar");
    renderSidebarLibrary($("#ex-lib-sb-search")?.value || "");
  }
  function hideLibSidebar() {
    const layout = document.querySelector(".coach-layout");
    if (layout) layout.classList.remove("show-lib-sidebar");
  }

  // -------- Picker value tables --------
  const REPS_VALUES   = [...Array.from({ length: 30 }, (_, i) => String(i + 1)), "AMAP"];
  const SETS_VALUES   = ["1","2","3","4","5","6"];
  // The picker's cells are in the athlete's own unit — a kg gym counts in
  // 2.5s off a 20 kg bar, and offering it 5 lb steps converted to 2.27 kg
  // would be a grid of numbers nobody can load.
  const WEIGHT_RANGES_LB = [
    { label: "BW · Bar", values: ["BW", "BAR"] },
    { label: "5–100",   values: Array.from({length:20}, (_,i) => String((i+1)*5)) },
    { label: "105–200", values: Array.from({length:20}, (_,i) => String(105+i*5)) },
    { label: "205–300", values: Array.from({length:20}, (_,i) => String(205+i*5)) },
    { label: "305–400", values: Array.from({length:20}, (_,i) => String(305+i*5)) },
    { label: "405+",    values: Array.from({length:80}, (_,i) => String(405+i*5)) },
  ];
  const WEIGHT_RANGES_KG = [
    { label: "BW · Bar", values: ["BW", "BAR"] },
    { label: "2.5–50",   values: Array.from({length:20}, (_,i) => String((i+1)*2.5)) },
    { label: "52.5–100", values: Array.from({length:20}, (_,i) => String(52.5+i*2.5)) },
    { label: "102.5–150", values: Array.from({length:20}, (_,i) => String(102.5+i*2.5)) },
    { label: "152.5–200", values: Array.from({length:20}, (_,i) => String(152.5+i*2.5)) },
    { label: "205+",    values: Array.from({length:80}, (_,i) => String(205+i*2.5)) },
  ];
  function weightRanges(u) { return isKg(u) ? WEIGHT_RANGES_KG : WEIGHT_RANGES_LB; }
  // The band boundaries each tab covers, so the picker can open on the tab
  // holding the current weight.
  function weightRangeTops(u) { return isKg(u) ? [50, 100, 150, 200] : [100, 200, 300, 400]; }

  function _positionPop(pop, anchor) {
    const r = anchor.getBoundingClientRect();
    const pr = pop.getBoundingClientRect();
    let left = r.left;
    left = Math.max(8, Math.min(left, window.innerWidth - pr.width - 8));
    let top = r.bottom + 6;
    if (top + pr.height > window.innerHeight - 8) top = r.top - pr.height - 6;
    if (top < 8) top = 8;
    pop.style.left = left + "px";
    pop.style.top  = top  + "px";
    pop.style.visibility = "visible";
  }

  function _attachOutsideClose(pop, anchorEl) {
    const handler = (e) => {
      if (!pop.contains(e.target) && e.target !== anchorEl) {
        pop.remove();
        document.removeEventListener("mousedown", handler, true);
      }
    };
    document.addEventListener("mousedown", handler, true);
  }

  function openGridPicker(label, values, currentVal, cb, anchorEl, cols) {
    document.querySelector(".grid-picker-pop")?.remove();
    const pop = document.createElement("div");
    pop.className = "grid-picker-pop";
    pop.style.cssText = "position:fixed;z-index:9999;visibility:hidden";

    if (label) {
      const head = document.createElement("div");
      head.className = "grid-picker-head";
      head.textContent = label;
      pop.appendChild(head);
    }

    const numCols = cols || values.length; // for small sets: all in one row
    const grid = document.createElement("div");
    grid.className = "grid-picker-grid";
    grid.style.gridTemplateColumns = `repeat(${numCols}, 1fr)`;

    values.forEach(v => {
      const btn = document.createElement("button");
      btn.className = "grid-picker-cell" + (String(v) === String(currentVal) ? " active" : "");
      btn.textContent = String(v);
      btn.type = "button";
      btn.addEventListener("click", () => { pop.remove(); cb(String(v)); });
      grid.appendChild(btn);
    });
    pop.appendChild(grid);

    document.body.appendChild(pop);
    requestAnimationFrame(() => _positionPop(pop, anchorEl));
    _attachOutsideClose(pop, anchorEl);
  }

